		return CoordinateFrame();
	}

	Extents extents = part->getPrimitive()->getExtentsLocal();
	Vector3 corner = extents.max();

	Vector3 uv = Math::vector3Abs(objectToUvw(corner, faceId));
	uv.z = 0.0f;

	switch (leftRight) {
	case LEFT:
		uv.x = -uv.x;
		break;
	case CENTER_LR:
		uv.x = 0.0f;
		break;
	}

	switch (topBottom) {
	case CENTER_TB:
		uv.y = 0.0f;
		break;
	case BOTTOM:
		uv.y = -uv.y;
		break;
